<script lang="ts" setup>import { reactive, ref } from "vue"
import { z } from "astro/zod"
import RLVForm from "@rimelight/ui/components/vue/RLVForm.vue"
import RLVFormField from "@rimelight/ui/components/vue/RLVFormField.vue"
import RLVInput from "@rimelight/ui/components/vue/RLVInput.vue"
import RLVButton from "@rimelight/ui/components/vue/RLVButton.vue"
import RLVCheckbox from "@rimelight/ui/components/vue/RLVCheckbox.vue"
const {  recovery = true,  terms = true,  remember = true,  messages = {}} = defineProps<{  recovery?: boolean  terms?: boolean  remember?: boolean  messages?: Record<string, string>}>();
const schema = z.object({  email: z.string().email(messages.auth_email_invalid ?? "Invalid email"),  password: z    .string()    .min(8, messages.auth_password_min_length ?? "Password must be at least 8 characters"),  rememberMe: z.boolean()});
type Schema = z.infer<typeof schema>;
const state = reactive<Partial<Schema>>({  email: "",  password: "",  rememberMe: remember});
const isLoading = ref(false);
const error = ref("");
const success = ref("");
const showPassword = ref(false);
function getRedirectParam(): string {  if (typeof window === "undefined") return "/"  const params = new URLSearchParams(window.location.search)  return params.get("redirect") || "/"}
async function onSubmit(event: { data: Schema }) {  isLoading.value = true  error.value = ""  success.value = ""  const { authClient } = await import("@/auth/auth-client")  const { error: signInError } = await authClient.signIn.email({    email: event.data.email,    password: event.data.password,    rememberMe: event.data.rememberMe  })  if (signInError) {    error.value =      signInError.message ?? messages.auth_connection_error_description ?? "Something went wrong"    isLoading.value = false    return  }  success.value = messages.auth_sign_in_success_title || "Signed in successfully"  isLoading.value = false  window.location.href = getRedirectParam()}</script><template>  <div class="w-full flex flex-col gap-lg max-w-md">    <p v-if="error" class="text-sm text-error-500">{{ error }}</p>    <p v-if="success" class="text-sm text-success-500">{{ success }}</p>    <RLVForm      :schema="schema"      :state="state"      class="flex flex-col gap-md text-left"      @submit="onSubmit"    >      <RLVFormField        :label="messages.auth_email_label ?? 'E-mail'"        name="email"        :description="messages.auth_email_description ?? ''"        required        class="text-black"        :ui="{          label: 'text-sm',          description: 'text-sm text-dimmed',          help: 'text-xs text-dimmed'        }"      >        <RLVInput          v-model="state.email"          type="email"          :placeholder="messages.auth_email_placeholder ?? 'your@email.com'"          class="w-full"        >          <template v-if="state.email?.length" #trailing>            <RLVButton              color="neutral"              variant="link"              size="sm"              icon="lucide:circle-x"              aria-label="Clear input"              @click="state.email = ''"            />          </template>        </RLVInput>        <template v-if="recovery" #help>          <a href="/auth/recovery" class="text-xs text-dimmed">            {{ messages["auth_sign-in_email_help"] ?? "Recover email" }}          </a>        </template>      </RLVFormField>      <RLVFormField        :label="messages.auth_password_label ?? 'Password'"        name="password"        :description="messages.auth_password_description ?? ''"        required        :ui="{          label: 'text-sm',          description: 'text-sm text-dimmed',          help: 'text-xs text-dimmed'        }"      >        <div class="flex flex-col gap-sm">          <RLVInput            v-model="state.password"            :type="showPassword ? 'text' : 'password'"            placeholder="••••••••••••••••"            class="w-full"          >            <template #trailing>              <RLVButton                color="neutral"                variant="link"                size="sm"                :icon="showPassword ? 'lucide:eye-off' : 'lucide:eye'"                :aria-label="showPassword ? 'Hide password' : 'Show password'"                :aria-pressed="showPassword"                aria-controls="password"                @click="showPassword = !showPassword"              />            </template>          </RLVInput>        </div>        <template v-if="recovery" #help>          <a href="/auth/recovery" class="text-xs text-dimmed">            {{ messages["auth_sign-in_password_help"] ?? "Forgot password?" }}          </a>        </template>      </RLVFormField>      <RLVCheckbox        v-if="remember"        v-model="state.rememberMe"        name="rememberMe"        :label="messages.auth_remember_me ?? 'Remember me'"      />      <RLVButton        color="primary"        variant="solid"        type="submit"        block        :loading="isLoading"        :disabled="isLoading"      >        {{ messages.auth_sign_in_button ?? "Sign in" }}      </RLVButton>    </RLVForm>    <template v-if="terms">      <span class="text-center text-sm text-black">        {{ messages.auth_terms_agreement ?? "By signing in you agree to our" }}        <a href="/documents/terms-of-service" class="font-medium text-primary hover:text-dimmed">          {{ messages.auth_terms_link ?? "Terms of Service" }} </a        >.      </span>    </template>  </div></template>